1	/**
2	 * Agentic Financial Analyst — Frontend Application
3	 *
4	 * Manages:
5	 *  - WebSocket connection lifecycle
6	 *  - Tab switching (Analysis / Reasoning Steps)
7	 *  - Real-time event routing to the correct UI handler
8	 *  - Markdown rendering via marked.js
9	 *  - Base64 figure rendering (matplotlib charts)
10	 *  - Auto-scroll to the latest message
11	 */
12	
13	'use strict';
14	
15	// ── DOM References ──────────────────────────────────────────────────────────
16	const tickerInput       = document.getElementById('tickerInput');
17	const queryInput        = document.getElementById('queryInput');
18	const startBtn          = document.getElementById('startBtn');
19	const tickerError       = document.getElementById('tickerError');
20	const connectionBadge   = document.getElementById('connectionBadge');
21	const statusBar         = document.getElementById('statusBar');
22	const statusText        = document.getElementById('statusText');
23	const messagesContainer = document.getElementById('messagesContainer');
24	const typingIndicator   = document.getElementById('typingIndicator');
25	const stepsContainer    = document.getElementById('stepsContainer');
26	const stepsEmpty        = document.getElementById('stepsEmpty');
27	const stepBadge         = document.getElementById('stepBadge');
28	const tabBtns           = document.querySelectorAll('.tab-btn');
29	const tabPanels         = document.querySelectorAll('.tab-panel');
30	
31	// ── State ────────────────────────────────────────────────────────────────────
32	let ws          = null;
33	let sessionId   = null;
34	let stepCount   = 0;
35	let analysisRunning = false;
36	
37	// ── Marked.js configuration ──────────────────────────────────────────────────
38	if (typeof marked !== 'undefined') {
39	  marked.setOptions({
40	    breaks: true,
41	    gfm: true,
42	  });
43	}
44	
45	function renderMarkdown(text) {
46	  if (typeof marked !== 'undefined') {
47	    return marked.parse(text);
48	  }
49	  // Fallback: escape HTML and preserve line breaks
50	  return text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
51	             .replace(/\n/g,'<br>');
52	}
53	
54	// ── Tab switching ────────────────────────────────────────────────────────────
55	tabBtns.forEach(btn => {
56	  btn.addEventListener('click', () => {
57	    const target = btn.dataset.tab;
58	    tabBtns.forEach(b => b.classList.toggle('active', b === btn));
59	    tabPanels.forEach(p => {
60	      p.classList.toggle('active',  p.id === `tab-${target}`);
61	      p.classList.toggle('hidden',  p.id !== `tab-${target}`);
62	    });
63	  });
64	});
65	
66	// ── WebSocket ────────────────────────────────────────────────────────────────
67	function generateSessionId() {
68	  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
69	    const r = Math.random() * 16 | 0;
70	    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
71	  });
72	}
73	
74	function connect() {
75	  sessionId = generateSessionId();
76	  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
77	  const url   = `${proto}://${location.host}/ws/${sessionId}`;
78	
79	  ws = new WebSocket(url);
80	
81	  ws.onopen = () => {
82	    setConnectionStatus('connected', 'Connected');
83	    startBtn.disabled = false;
84	  };
85	
86	  ws.onmessage = (e) => {
87	    try {
88	      const event = JSON.parse(e.data);
89	      routeEvent(event);
90	    } catch (err) {
91	      console.error('Failed to parse event:', e.data, err);
92	    }
93	  };
94	
95	  ws.onclose = () => {
96	    setConnectionStatus('disconnected', 'Disconnected — reconnecting…');
97	    startBtn.disabled = true;
98	    setAnalysisRunning(false);
99	    setTimeout(connect, 3000);
100	  };
101	
102	  ws.onerror = (err) => {
103	    console.error('WebSocket error:', err);
104	    setConnectionStatus('error', 'Connection error');
105	  };
106	}
107	
108	// ── Connection status ────────────────────────────────────────────────────────
109	function setConnectionStatus(state, label) {
110	  connectionBadge.className = `connection-badge ${state}`;
111	  connectionBadge.innerHTML = `<span class="dot"></span> ${label}`;
112	}
113	
114	// ── Analysis lifecycle ────────────────────────────────────────────────────────
115	function setAnalysisRunning(running) {
116	  analysisRunning = running;
117	  tickerInput.disabled = running;
118	  queryInput.disabled  = running;
119	  startBtn.disabled    = running || !ws || ws.readyState !== WebSocket.OPEN;
120	  if (running) {
121	    typingIndicator.classList.remove('hidden');
122	    statusBar.classList.add('active');
123	  } else {
124	    typingIndicator.classList.add('hidden');
125	    statusBar.classList.remove('active');
126	  }
127	}
128	
129	// ── Start button ──────────────────────────────────────────────────────────────
130	startBtn.addEventListener('click', () => {
131	  const ticker = tickerInput.value.trim().toUpperCase();
132	  const query  = queryInput.value.trim()
133	    || `Perform a comprehensive financial analysis of ${ticker}.`;
134	
135	  if (!ticker) {
136	    showTickerError('Please enter a stock ticker or company name.');
137	    return;
138	  }
139	  hideTickerError();
140	
141	  if (!ws || ws.readyState !== WebSocket.OPEN) {
142	    showTickerError('Not connected to server. Please wait and try again.');
143	    return;
144	  }
145	
146	  // Clear previous analysis
147	  clearMessages();
148	  clearSteps();
149	  queryInput.style.height = '';  // reset textarea height
150	  setAnalysisRunning(true);
151	  setStatus('⏳', `Sending request for ${ticker}...`);
152	
153	  // Add user bubble — show the full query text (including the generated default)
154	  addMessage('user', ticker + ' — ' + query);
155	
156	  // Send to server
157	  ws.send(JSON.stringify({ ticker, query }));
158	});
159	
160	// Enter on ticker input submits; Shift+Enter on query textarea inserts newline (default),
161	// plain Enter on query textarea also submits for convenience.
162	tickerInput.addEventListener('keydown', e => {
163	  if (e.key === 'Enter') startBtn.click();
164	});
165	queryInput.addEventListener('keydown', e => {
166	  if (e.key === 'Enter' && !e.shiftKey) {
167	    e.preventDefault();
168	    startBtn.click();
169	  }
170	});
171	
172	// Auto-grow textarea as user types
173	queryInput.addEventListener('input', () => {
174	  queryInput.style.height = 'auto';
175	  queryInput.style.height = Math.min(queryInput.scrollHeight, 200) + 'px';
176	});
177	
178	// ── Event router ──────────────────────────────────────────────────────────────
179	const EVENT_ICONS = {
180	  session_ready:    '🟢',
181	  validation_error: '❌',
182	  agent_start:      '🚀',
183	  agent_done:       '✅',
184	  tool_call:        '🔧',
185	  tool_result:      '📦',
186	  synthesis_start:  '🔗',
187	  synthesis_done:   '✅',
188	  critique_start:   '🔎',
189	  critique_done:    '🏷️',
190	  rerun_start:      '🔄',
191	  final_output:     '📊',
192	  abstain:          '⚠️',
193	  error:            '🚨',
194	};
195	
196	function routeEvent(event) {
197	  const { event_type, agent_name, message, payload, timestamp } = event;
198	
199	  // Always add to steps tab — pass full payload for rich rendering
200	  addStep(event_type, agent_name, message, timestamp, payload);
201	
202	  switch (event_type) {
203	    case 'session_ready':
204	      setStatus('🟢', message);
205	      break;
206	
207	    case 'validation_error':
208	      showTickerError(message);
209	      setAnalysisRunning(false);
210	      setStatus('❌', 'Invalid ticker entered.');
211	      break;
212	
213	    case 'agent_start':
214	    case 'synthesis_start':
215	    case 'critique_start':
216	    case 'rerun_start':
217	      setStatus(EVENT_ICONS[event_type] || '⏳', message);
218	      break;
219	
220	    case 'agent_done':
221	    case 'synthesis_done':
222	    case 'critique_done':
223	      setStatus(EVENT_ICONS[event_type] || '✅', message);
224	      break;
225	
226	    case 'tool_call':
227	      setStatus('🔧', message);
228	      break;
229	
230	    case 'final_output': {
231	      setAnalysisRunning(false);
232	      setStatus('✅', 'Analysis complete.');
233	      const narrative = (payload && payload.narrative) || message;
234	      addAgentMessage(narrative, payload);
235	      break;
236	    }
237	
238	    case 'abstain':
239	      setAnalysisRunning(false);
240	      setStatus('⚠️', 'Analysis could not be completed.');
241	      addAgentMessage(message, payload);
242	      break;
243	
244	    case 'error':
245	      setAnalysisRunning(false);
246	      setStatus('🚨', message);
247	      addAgentMessage(`**Error:** ${message}`, null);
248	      break;
249	
250	    default:
251	      setStatus('ℹ️', message);
252	  }
253	}
254	
255	// ── UI helpers ────────────────────────────────────────────────────────────────
256	function setStatus(icon, text) {
257	  document.querySelector('.status-icon').textContent = icon;
258	  statusText.textContent = text;
259	}
260	
261	function showTickerError(msg) {
262	  tickerError.innerHTML = msg;
263	  tickerError.classList.remove('hidden');
264	}
265	function hideTickerError() {
266	  tickerError.classList.add('hidden');
267	}
268	
269	function clearMessages() {
270	  messagesContainer.innerHTML = '';
271	}
272	function clearSteps() {
273	  stepsContainer.innerHTML = '';
274	  stepsEmpty.style.display = 'block';
275	  stepsContainer.appendChild(stepsEmpty);
276	  stepCount = 0;
277	  stepBadge.textContent = '0';
278	}
279	
280	function addMessage(role, text) {
281	  const isAgent = role === 'agent';
282	  const div = document.createElement('div');
283	  div.className = `message ${isAgent ? 'agent-message' : 'user-message'}`;
284	  div.innerHTML = `
285	    <div class="message-avatar">${isAgent ? '🤖' : '👤'}</div>
286	    <div class="message-bubble">${isAgent ? renderMarkdown(text) : escapeHtml(text)}</div>
287	  `;
288	  messagesContainer.appendChild(div);
289	  scrollToBottom(messagesContainer);
290	}
291	
292	function addAgentMessage(markdown, payload) {
293	  const div = document.createElement('div');
294	  div.className = 'message agent-message';
295	
296	  let figuresHtml = '';
297	  if (payload && payload.figures && payload.figures.length > 0) {
298	    figuresHtml = payload.figures.map(b64 =>
299	      `<img class="chart-img" src="data:image/png;base64,${b64}" alt="Analysis chart" />`
300	    ).join('');
301	  }
302	
303	  div.innerHTML = `
304	    <div class="message-avatar">🤖</div>
305	    <div class="message-bubble">
306	      ${renderMarkdown(markdown)}
307	      ${figuresHtml}
308	    </div>
309	  `;
310	  messagesContainer.appendChild(div);
311	  scrollToBottom(messagesContainer);
312	}
313	
314	function addStep(event_type, agent_name, message, timestamp, payload) {
315	  // Remove empty placeholder
316	  if (stepsEmpty && stepsEmpty.parentNode) {
317	    stepsEmpty.parentNode.removeChild(stepsEmpty);
318	  }
319	
320	  stepCount++;
321	  stepBadge.textContent = stepCount;
322	
323	  const icon = EVENT_ICONS[event_type] || 'ℹ️';
324	  const time = timestamp ? new Date(timestamp).toLocaleTimeString() : '';
325	
326	  // Build rich detail panel for specific event types
327	  let detailHtml = '';
328	  if (event_type === 'agent_done' && payload && payload.claims) {
329	    detailHtml = buildSpecialistDetail(payload);
330	  } else if (event_type === 'synthesis_done' && payload) {
331	    detailHtml = buildSynthesisDetail(payload);
332	  } else if (event_type === 'critique_done' && payload && payload.critique) {
333	    detailHtml = buildCritiqueDetail(payload.critique);
334	  }
335	
336	  const item = document.createElement('div');
337	  item.className = `step-item step-${event_type}`;
338	  item.innerHTML = `
339	    <div class="step-icon">${icon}</div>
340	    <div class="step-body">
341	      <div class="step-meta">
342	        ${agent_name ? `<span class="step-agent-tag">${escapeHtml(agent_name)}</span>` : ''}
343	        ${time ? `<span class="step-time">${time}</span>` : ''}
344	      </div>
345	      <div class="step-message">${escapeHtml(message)}</div>
346	      ${detailHtml ? `<details class="step-detail"><summary>View details</summary><div class="step-detail-content">${detailHtml}</div></details>` : ''}
347	    </div>
348	  `;
349	  stepsContainer.appendChild(item);
350	  scrollToBottom(stepsContainer);
351	}
352	
353	// ── Rich detail builders ──────────────────────────────────────────────────────
354	
355	/** Returns a safe http/https URL or null. */
356	function safeUrl(url) {
357	  if (!url || typeof url !== 'string') return null;
358	  return (url.startsWith('http://') || url.startsWith('https://')) ? url : null;
359	}
360	
361	/** Returns a short human-readable label for a URL (hostname only). */
362	function urlLabel(url) {
363	  try {
364	    const hostname = new URL(url).hostname.replace(/^www\./, '');
365	    return hostname + ' \u2197'; // ↗ external-link symbol
366	  } catch {
367	    return url.length > 50 ? url.slice(0, 50) + '\u2026' : url;
368	  }
369	}
370	
371	function buildSpecialistDetail(payload) {
372	  const pct = payload.confidence !== undefined ? Math.round(payload.confidence * 100) : 0;
373	  const confColor = pct >= 70 ? 'var(--success)' : pct >= 40 ? 'var(--warning)' : 'var(--danger)';
374	
375	  let html = '';
376	
377	  // Confidence
378	  html += `<div class="step-dl-row">
379	    <span class="step-dl-label">Confidence</span>
380	    <div class="step-conf-bar"><div class="step-conf-fill" style="width:${pct}%;background:${confColor}"></div></div>
381	    <span class="step-conf-pct" style="color:${confColor}">${pct}%</span>
382	  </div>`;
383	
384	  // Claims
385	  if (payload.claims && payload.claims.length > 0) {
386	    html += `<div class="step-dl-label">Key Claims</div><ul class="step-claims">`;
387	    payload.claims.forEach(c => { html += `<li>${escapeHtml(c)}</li>`; });
388	    html += `</ul>`;
389	  }
390	
391	  // Evidence
392	  if (payload.evidence && payload.evidence.length > 0) {
393	    html += `<div class="step-dl-label">Evidence &amp; Sources</div>`;
394	    payload.evidence.forEach(ev => {
395	      const link = safeUrl(ev.source_url);
396	      const filingId = ev.filing_identifier;
397	      html += `<div class="step-evidence-item">
398	        <span class="step-source-badge">${escapeHtml(ev.source_type || '')}</span>
399	        <span class="step-evidence-text">${escapeHtml((ev.text || '').slice(0, 220))}${(ev.text || '').length > 220 ? '…' : ''}</span>
400	        ${link ? `<div><a class="step-source-link" href="${escapeHtml(link)}" target="_blank" rel="noopener noreferrer">${escapeHtml(urlLabel(link))}</a></div>` : ''}
401	        ${!link && filingId ? `<div class="step-filing-id">${escapeHtml(filingId)}</div>` : ''}
402	      </div>`;
403	    });
404	  }
405	
406	  // Failure reason
407	  if (!payload.success && payload.failure_reason) {
408	    html += `<div class="step-failure"><span class="step-dl-label">Failure Reason</span> ${escapeHtml(payload.failure_reason)}</div>`;
409	  }
410	
411	  return html;
412	}
413	
414	function buildSynthesisDetail(payload) {
415	  let html = '';
416	
417	  if (payload.key_hypothesis) {
418	    html += `<div class="step-dl-label">Key Hypothesis</div>
419	    <div class="step-hypothesis">${escapeHtml(payload.key_hypothesis)}</div>`;
420	  }
421	
422	  if (payload.sources && payload.sources.length > 0) {
423	    const shown = payload.sources.slice(0, 10);
424	    const rest  = payload.sources.length - shown.length;
425	    html += `<div class="step-dl-label">Sources (${payload.sources.length})</div><ul class="step-sources">`;
426	    shown.forEach(src => {
427	      const link = safeUrl(src);
428	      html += `<li>${link ? `<a class="step-source-link" href="${escapeHtml(link)}" target="_blank" rel="noopener noreferrer">${escapeHtml(urlLabel(link))}</a>` : escapeHtml(src)}</li>`;
429	    });
430	    if (rest > 0) html += `<li class="step-more">…and ${rest} more</li>`;
431	    html += `</ul>`;
432	  }
433	
434	  if (payload.omitted_specialists && payload.omitted_specialists.length > 0) {
435	    html += `<div class="step-failure"><span class="step-dl-label">Omitted Specialists</span> ${escapeHtml(payload.omitted_specialists.join(', '))}</div>`;
436	  }
437	
438	  return html;
439	}
440	
441	function buildCritiqueDetail(critique) {
442	  if (!critique) return '';
443	
444	  const sevColor = { none: 'var(--success)', low: 'var(--text-secondary)', medium: 'var(--warning)', high: 'var(--danger)' };
445	  const sev = critique.overall_severity || 'none';
446	
447	  let html = `<div class="step-dl-row">
448	    <span class="step-dl-label">Overall Severity</span>
449	    <span class="step-sev-badge" style="color:${sevColor[sev] || 'inherit'}">${sev.toUpperCase()}</span>
450	  </div>`;
451	
452	  if (critique.critique_summary) {
453	    html += `<div class="step-critique-summary">${escapeHtml(critique.critique_summary)}</div>`;
454	  }
455	
456	  if (critique.issues && critique.issues.length > 0) {
457	    html += `<div class="step-dl-label">Issues (${critique.issues.length})</div>`;
458	    critique.issues.forEach(issue => {
459	      const isevColor = sevColor[issue.severity] || 'inherit';
460	      html += `<div class="step-issue-item">
461	        <div class="step-issue-header">
462	          <span class="step-sev-badge" style="color:${isevColor}">${(issue.severity || '').toUpperCase()}</span>
463	          <span class="step-issue-tag">${escapeHtml(issue.tag || '')}</span>
464	          <span class="step-issue-agent">${escapeHtml(issue.affected_specialist || '')}</span>
465	        </div>
466	        <div class="step-issue-quote">"${escapeHtml((issue.quote || '').slice(0, 180))}${(issue.quote || '').length > 180 ? '…' : ''}"</div>
467	        ${issue.suggestion ? `<div class="step-issue-suggestion">${escapeHtml(issue.suggestion)}</div>` : ''}
468	      </div>`;
469	    });
470	  }
471	
472	  return html;
473	}
474	
475	function scrollToBottom(el) {
476	  // If the element is a constrained scroll container, scroll it directly.
477	  // Otherwise fall back to scrolling the last child into view (e.g. steps tab).
478	  if (el.scrollHeight > el.clientHeight && getComputedStyle(el).overflowY !== 'visible') {
479	    el.scrollTop = el.scrollHeight;
480	  } else {
481	    el.lastElementChild?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
482	  }
483	}
484	
485	function escapeHtml(str) {
486	  return String(str)
487	    .replace(/&/g, '&amp;')
488	    .replace(/</g, '&lt;')
489	    .replace(/>/g, '&gt;')
490	    .replace(/"/g, '&quot;');
491	}
492	
493	// ── Init ─────────────────────────────────────────────────────────────────────
494	connect();
495

